const sql=require("mssql"),{getSourceConfig:getSourceConfig}=require("../db.helper"),mssqlConfig=getSourceConfig(),CLINIC_ID=1;class DataMigrator{constructor(){this.mssqlPool=null,this.stats={users:0,services:0,patients:0,appointments:0,items:0,examinations:0}}async connect(){this.mssqlPool=await sql.connect(mssqlConfig)}async disconnect(){this.mssqlPool&&await this.mssqlPool.close()}async extractUsers(){const t=(await this.mssqlPool.request().query("\n            SELECT \n                TAKIPNO,\n                GIRISKODU,\n                ISIMSOYISIM,\n                GOREVNO,\n                IPTAL\n            FROM KULLANICILAR\n            WHERE TAKIPNO > 0\n            ORDER BY TAKIPNO\n        ")).recordset.map((t=>({legacy_id:t.TAKIPNO,username:(t.GIRISKODU||`user_${t.TAKIPNO}`).toLowerCase().substring(0,50),name:t.ISIMSOYISIM||`Kullanıcı ${t.TAKIPNO}`,role:this.mapUserRole(t.GOREVNO),is_active:t.IPTAL?0:1})));return this.stats.users=t.length,t}mapUserRole(t){switch(t){case 2:return"doctor";case 16:case 11:return"secretary";default:return"admin"}}async extractServices(){const t=(await this.mssqlPool.request().query("\n            SELECT \n                KOD,\n                ACIKLAMA,\n                FIYAT,\n                BUTFIYATI,\n                IPTAL\n            FROM TETKIK\n            WHERE ACIKLAMA IS NOT NULL AND ACIKLAMA != ''\n            ORDER BY KOD\n        ")).recordset.map((t=>({legacy_code:String(t.KOD),name:t.ACIKLAMA,price:t.FIYAT||t.BUTFIYATI||0,is_active:t.IPTAL?0:1})));return this.stats.services=t.length,t}async extractPatients(){const t=(await this.mssqlPool.request().query("\n            SELECT \n                HASTANO,\n                AD, SOYAD, KIMLIKNO,\n                EV_TELEFON, EV_MOBIL, EV_EMAIL,\n                DGMTRH, DOGUMYERI, CINSIYET, KANGRUBU,\n                EV_ADRES1, EV_ADRES2, EV_ADRES_SEMT, EV_ADRES_ILCE, EV_ADRES_IL,\n                BABAADI, ANNEADI, MESLEK, NK_UYRUGU, NOTLAR,\n                ILACALERJISI, MADDEALERJISI, TIBBIUYARI,\n                ARSIVNO, AILENO, K_HASTANO,\n                HASTALIK_DIYABET, HASTALIK_HEPATIT, HASTALIK_HIV, HASTALIK_COVID, HASTALIK_DIGER,\n                SIGORTA_POLICENO, SGK_KURUM, SGK_SOSYALGUVNO,\n                IPTAL\n            FROM HST_ANADOSYA\n            ORDER BY HASTANO\n        ")).recordset.map((t=>{const n=[];t.HASTALIK_DIYABET&&n.push("Diyabet"),t.HASTALIK_HEPATIT&&n.push("Hepatit"),t.HASTALIK_HIV&&"H"!==t.HASTALIK_HIV&&n.push("HIV"),t.HASTALIK_COVID&&n.push("COVID"),t.HASTALIK_DIGER&&n.push(t.HASTALIK_DIGER);const e=[t.EV_ADRES1,t.EV_ADRES2,t.EV_ADRES_SEMT].filter((t=>t&&t.trim())).join(", ");return{legacy_id:t.HASTANO,name:`${t.AD||""} ${t.SOYAD||""}`.trim()||`Hasta ${t.HASTANO}`,tc_no:t.KIMLIKNO||"",phone:t.EV_MOBIL||t.EV_TELEFON||"",email:t.EV_EMAIL||null,birth_date:t.DGMTRH?new Date(t.DGMTRH).toISOString().split("T")[0]:null,birth_place:t.DOGUMYERI||null,gender:"E"===t.CINSIYET?"M":"K"===t.CINSIYET?"F":"U",blood_type:t.KANGRUBU||null,address:e||null,city:t.EV_ADRES_IL||null,district:t.EV_ADRES_ILCE||null,father_name:t.BABAADI||null,mother_name:t.ANNEADI||null,profession:t.MESLEK||null,nationality:t.NK_UYRUGU||"TR",notes:t.NOTLAR||null,status:t.IPTAL?0:1,extra_metadata:{medical:{allergies:{drug:t.ILACALERJISI||null,substance:t.MADDEALERJISI||null},chronic_diseases:n,medical_warnings:t.TIBBIUYARI||null},archival:{archive_no:t.ARSIVNO||null,family_no:t.AILENO||null,k_hastano:t.K_HASTANO||null},insurance:{policy_no:t.SIGORTA_POLICENO||null,institution:t.SGK_KURUM||null,social_security_no:t.SGK_SOSYALGUVNO||null}}}}));return this.stats.patients=t.length,t}async extractAppointments(){const t=(await this.mssqlPool.request().query("\n            SELECT \n                GELISNO,\n                PROTOKOLNO,\n                HASTANO,\n                DOKTOR_ID,\n                TARIH,\n                IPTAL\n            FROM HST_GELISLER\n            ORDER BY GELISNO\n        ")).recordset.map((t=>({legacy_visit_id:t.GELISNO,protocol_no:t.PROTOKOLNO||null,patient_legacy_id:t.HASTANO,doctor_legacy_id:t.DOKTOR_ID,appointment_date:t.TARIH?new Date(t.TARIH).toISOString().slice(0,19).replace("T"," "):null,status:t.IPTAL?"cancelled":"completed"})));return this.stats.appointments=t.length,t}async extractAppointmentItems(){const t=(await this.mssqlPool.request().query("\n            SELECT \n                i.RECORD_ID,\n                i.GELISNO,\n                i.ISLEMNO,\n                i.FIYAT,\n                i.ADET,\n                i.YAPAN,\n                t.ACIKLAMA as ISLEM_ADI\n            FROM HST_ISLEMLER i\n            LEFT JOIN TETKIK t ON i.ISLEMNO = t.KOD\n            ORDER BY i.GELISNO, i.RECORD_ID\n        ")).recordset.map((t=>({appointment_legacy_id:t.GELISNO,service_legacy_code:String(t.ISLEMNO),item_name:t.ISLEM_ADI||`İşlem ${t.ISLEMNO}`,quantity:t.ADET||1,unit_price:parseFloat(t.FIYAT)||0,total_price:(parseFloat(t.FIYAT)||0)*(t.ADET||1),performer_legacy_id:t.YAPAN})));return this.stats.items=t.length,t}async extractExaminations(){const t=(await this.mssqlPool.request().query("\n            SELECT \n                t.GELISNO,\n                et.SIKAYETLER,\n                et.HIKAYESI,\n                et.BULGULAR,\n                et.TESHIS,\n                et.TEDAVI,\n                et.SONUC,\n                et.TARIH\n            FROM HST_TIBBI_EPIKRIZ_TAKIP et\n            INNER JOIN HST_TIBBI_EPIKRIZ e ON et.EPIKRIZ_ID = e.ID\n            INNER JOIN HST_TIBBI t ON e.TIBBIDOSYA_ID = t.RECORD_ID\n            ORDER BY et.EPIKRIZ_ID\n        ")).recordset.map((t=>({legacy_visit_id:t.GELISNO,complaint:t.SIKAYETLER||null,story:t.HIKAYESI||null,bulgular:t.BULGULAR||null,diagnosis:t.TESHIS||null,treatment:t.TEDAVI||null,result_note:t.SONUC||null,created_at:t.TARIH?new Date(t.TARIH).toISOString().slice(0,19).replace("T"," "):null})));return this.stats.examinations=t.length,t}async extractAll(){await this.connect();try{const t={clinic_id:1,extracted_at:(new Date).toISOString(),users:await this.extractUsers(),services:await this.extractServices(),patients:await this.extractPatients(),appointments:await this.extractAppointments(),appointment_items:await this.extractAppointmentItems(),examinations:await this.extractExaminations()},n=require("fs"),e=require("path").resolve(__dirname,"..","data","migration_data.json");return n.writeFileSync(e,JSON.stringify(t,null,2)),t}finally{await this.disconnect()}}}const migrator=new DataMigrator;migrator.extractAll().catch((t=>{process.exit(1)}));